import{_ as e,c as t,o,a2 as r}from"./chunks/framework.DgH2I27U.js";const b=JSON.parse('{"title":"Fork Git et GitHub","description":"","frontmatter":{},"headers":[],"relativePath":"fr/contribute/fork.md","filePath":"fr/contribute/fork.md"}'),a={name:"fr/contribute/fork.md"},u=r('<h1 id="fork-git-et-github" tabindex="-1">Fork Git et GitHub <a class="header-anchor" href="#fork-git-et-github" aria-label="Permalink to &quot;Fork Git et GitHub&quot;">​</a></h1><h2 id="ajouter-au-depot-de-quelqu-un-d-autre" tabindex="-1">Ajouter au Dépôt de Quelqu&#39;un d&#39;Autre <a class="header-anchor" href="#ajouter-au-depot-de-quelqu-un-d-autre" aria-label="Permalink to &quot;Ajouter au Dépôt de Quelqu&#39;un d&#39;Autre&quot;">​</a></h2><p>Au cœur de Git se trouve la collaboration. Cependant, Git ne permet pas d&#39;ajouter du code dans le dépôt de quelqu&#39;un d&#39;autre sans les droits d&#39;accès nécessaires.</p><p>Dans les trois prochains chapitres, nous allons vous montrer comment copier un dépôt, y apporter des modifications, puis suggérer que ces changements soient implémentés dans le dépôt original.</p><p>À la fin de ces chapitres, vous aurez la possibilité d&#39;ajouter un message à notre page publique sur GitHub : <a href="https://w3schools-test.github.io/" target="_blank" rel="noreferrer">Page GitHub Publique</a></p><h2 id="forker-un-depot" tabindex="-1">Forker un Dépôt <a class="header-anchor" href="#forker-un-depot" aria-label="Permalink to &quot;Forker un Dépôt&quot;">​</a></h2><p>Un <strong>fork</strong> est une copie d&#39;un dépôt. Cela est utile lorsque vous souhaitez contribuer à un projet existant ou démarrer votre propre projet basé sur celui d&#39;un autre.</p><p>Bien que <strong>fork</strong> ne soit pas une commande Git, c&#39;est une fonctionnalité offerte par GitHub et d&#39;autres hébergeurs de dépôts. Commençons par nous connecter à GitHub et créer un fork de notre dépôt.</p><h3 id="etapes-pour-forker-un-depot" tabindex="-1">Étapes pour Forker un Dépôt <a class="header-anchor" href="#etapes-pour-forker-un-depot" aria-label="Permalink to &quot;Étapes pour Forker un Dépôt&quot;">​</a></h3><ol><li>Connectez-vous à GitHub.</li><li>Allez sur le dépôt que vous souhaitez forker :<br><a href="https://github.com/w3schools-test/w3schools-test.github.io" target="_blank" rel="noreferrer">w3schools-test.github.io</a></li><li>Cliquez sur le bouton <strong>Fork</strong> situé en haut à droite de la page.</li></ol><p>Une fois cette étape terminée, vous aurez votre propre copie du dépôt <code>w3schools-test.github.io</code> sur votre compte GitHub.</p><h3 id="fork-github-complet" tabindex="-1">Fork GitHub Complet <a class="header-anchor" href="#fork-github-complet" aria-label="Permalink to &quot;Fork GitHub Complet&quot;">​</a></h3><p>Vous avez maintenant votre propre copie du dépôt <code>w3schools-test.github.io</code> et vous êtes prêt à apporter des modifications à votre version locale.</p><h2 id="ajouter-une-copie-locale-pour-travailler" tabindex="-1">Ajouter une Copie Locale pour Travailler <a class="header-anchor" href="#ajouter-une-copie-locale-pour-travailler" aria-label="Permalink to &quot;Ajouter une Copie Locale pour Travailler&quot;">​</a></h2><p>Maintenant que vous avez un fork, il est temps de travailler dessus localement. Dans le chapitre suivant, nous verrons comment cloner ce dépôt sur votre machine et effectuer des modifications.</p>',15),s=[u];function i(n,l,p,c,d,h){return o(),t("div",null,s)}const m=e(a,[["render",i]]);export{b as __pageData,m as default};
